/**
 * The videocall signaling service.
 *
 * Rooms are in memory: a participant opens a WebSocket, the server keeps the room's participant
 * list, and every signaling message (offer, answer, ICE candidate), chat line and mute/camera
 * state goes through here. Media itself is peer-to-peer and never reaches this process.
 *
 * A room is created by its first participant and disappears with its last one. The room id is a
 * UUID generated by the browser, so a room can be shared before anyone joins and no room table is
 * needed. Authentication is the identity service's HttpOnly JWT cookie, read through the shared
 * library; the server fetches the identity public key at startup like organizator-server does.
 */
use std::collections::HashMap;
use std::sync::{Arc, Mutex};
use std::time::{Duration, SystemTime, UNIX_EPOCH};

use axum::extract::ws::{CloseFrame, Message, WebSocket, WebSocketUpgrade};
use axum::extract::{Path, State};
use axum::http::{HeaderMap, StatusCode, header};
use axum::response::{IntoResponse, Response};
use axum::routing::get;
use axum::{Json, Router};
use futures_util::stream::SplitSink;
use futures_util::{SinkExt, StreamExt};
use mimalloc::MiMalloc;
use serde::{Deserialize, Serialize};
use serde_json::json;
use tokio::sync::mpsc;
use tracing::{debug, info, warn};
use tracing_subscriber::EnvFilter;
use uuid::Uuid;

use lib_axum_organizator::security::check_security::extract_jwt;
use lib_axum_organizator::security::jot::{ExpiredToken, Jot, User};

mod settings;

use settings::Settings;

#[global_allocator]
static GLOBAL: MiMalloc = MiMalloc;

/// A WebSocket text/binary frame is small in this protocol — SDP and chat lines — so a large frame
/// is a client doing something the service does not need to support.
const MAX_MESSAGE_BYTES: usize = 64 * 1024;
const PING_SECONDS: u64 = 25;

/// How long to wait before asking the identity service for its public key again. The first
/// retry is quick; the wait doubles up to the cap so a deployment whose identity service is
/// down does not write a warning every second. The port is bound only once a key is loaded.
const PUBLIC_KEY_RETRY_START: Duration = Duration::from_secs(1);
const PUBLIC_KEY_RETRY_MAX: Duration = Duration::from_secs(30);

struct AppState {
    settings: Settings,
    jot: Jot,
    rooms: Mutex<HashMap<String, Room>>,
}

#[derive(Default)]
struct Room {
    participants: HashMap<Uuid, Participant>,
}

struct Participant {
    info: ParticipantInfo,
    tx: mpsc::UnboundedSender<ServerMessage>,
}

#[derive(Clone, Debug, Serialize)]
struct ParticipantInfo {
    id: Uuid,
    name: String,
    audio: bool,
    video: bool,
}

#[derive(Clone, Debug, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
struct IceCandidate {
    candidate: String,
    #[serde(default)]
    sdp_mid: Option<String>,
    #[serde(default)]
    sdp_m_line_index: Option<u16>,
    #[serde(default)]
    username_fragment: Option<String>,
}

#[derive(Debug, Deserialize)]
#[serde(tag = "type", rename_all = "kebab-case")]
enum ClientMessage {
    Offer { to: Uuid, sdp: String },
    Answer { to: Uuid, sdp: String },
    IceCandidate { to: Uuid, candidate: IceCandidate },
    Chat { text: String },
    State { audio: bool, video: bool },
}

#[derive(Clone, Debug, Serialize)]
#[serde(tag = "type", rename_all = "kebab-case")]
enum ServerMessage {
    Welcome {
        self_id: Uuid,
        room_id: String,
        participants: Vec<ParticipantInfo>,
    },
    PeerJoined {
        participant: ParticipantInfo,
    },
    PeerLeft {
        id: Uuid,
    },
    Offer {
        from: Uuid,
        sdp: String,
    },
    Answer {
        from: Uuid,
        sdp: String,
    },
    IceCandidate {
        from: Uuid,
        candidate: IceCandidate,
    },
    Chat {
        from: Uuid,
        name: String,
        text: String,
        at: u64,
    },
    ParticipantState {
        id: Uuid,
        audio: bool,
        video: bool,
    },
    Error {
        message: String,
    },
}

#[tokio::main]
async fn main() {
    tracing_subscriber::fmt()
        .with_env_filter(
            EnvFilter::try_from_default_env().unwrap_or_else(|_| EnvFilter::new("info")),
        )
        .init();

    let settings = Settings::new();
    info!("Starting videocall service on {}", settings.api_ip());
    let jot = load_jot(&settings).await;
    let state = Arc::new(AppState {
        settings,
        jot,
        rooms: Mutex::new(HashMap::new()),
    });

    let app = Router::new()
        .route("/health", get(health))
        .route("/ws/{room_id}", get(ws_handler))
        .with_state(state.clone());

    let listener = tokio::net::TcpListener::bind(state.settings.api_ip())
        .await
        .expect("Could not bind the videocall API address");
    info!("Listening on {}", listener.local_addr().unwrap());
    axum::serve(listener, app).await.unwrap();
}

/// Load the identity service's public key, waiting for the service if necessary.
///
/// On a machine that starts both services, systemd brings identity up first, but "started"
/// does not mean its HTTP server is accepting connections yet. The old code panicked here and
/// relied on `Restart=always` to try again; waiting is faster and leaves a readable log. Only a
/// configured URL can fail this way — without one, `Jot::new` generates a keypair locally.
async fn load_jot(settings: &Settings) -> Jot {
    let Some(url) = settings.security.public_key_url.as_deref() else {
        return Jot::new(&settings.security)
            .await
            .expect("Could not generate the identity keypair");
    };

    let mut delay = PUBLIC_KEY_RETRY_START;
    loop {
        match Jot::new(&settings.security).await {
            Ok(jot) => return jot,
            Err(error) => {
                warn!(
                    "Could not load the identity public key from {url}: {error:?}; retrying in {}s",
                    delay.as_secs()
                );
                tokio::time::sleep(delay).await;
                delay = (delay * 2).min(PUBLIC_KEY_RETRY_MAX);
            }
        }
    }
}

async fn health() -> Json<serde_json::Value> {
    Json(json!({"status": "ok"}))
}

/// The browser sends its origin on the WebSocket handshake. With a configured list, only those
/// origins may connect; an empty list is for local development and tests.
fn origin_allowed(headers: &HeaderMap, allowed: &[String]) -> bool {
    if allowed.is_empty() {
        return true;
    }
    headers
        .get(header::ORIGIN)
        .and_then(|value| value.to_str().ok())
        .is_some_and(|origin| allowed.iter().any(|allowed| allowed == origin))
}

/// Read the identity cookie or bearer token and validate it. A token in its grace period is still
/// valid; this service does not mint tokens, so it leaves refreshing to the identity service.
fn authenticate(headers: &HeaderMap, jot: &Jot) -> Result<User, &'static str> {
    let token = extract_jwt(headers).ok_or("No session")?;
    let claims = jot.validate_token(token).map_err(|_| "Invalid session")?;
    match jot.check_expiration(&claims) {
        ExpiredToken::Valid | ExpiredToken::GracePeriod => Ok(User::from(claims)),
        ExpiredToken::Expired => Err("Session expired"),
    }
}

async fn ws_handler(
    State(state): State<Arc<AppState>>,
    headers: HeaderMap,
    Path(room_id): Path<String>,
    ws: WebSocketUpgrade,
) -> Response {
    if !origin_allowed(&headers, &state.settings.allowed_origins) {
        warn!("Refused a WebSocket from an origin that is not allowed");
        return (StatusCode::FORBIDDEN, "Origin not allowed").into_response();
    }
    let user = match authenticate(&headers, &state.jot) {
        Ok(user) => user,
        Err(reason) => {
            debug!("Refused a WebSocket: {reason}");
            return (StatusCode::UNAUTHORIZED, reason).into_response();
        }
    };
    let room_id = match Uuid::parse_str(&room_id) {
        Ok(id) => id.to_string(),
        Err(_) => {
            return (StatusCode::BAD_REQUEST, "Room id must be a UUID").into_response();
        }
    };
    let name = user.id().to_string();
    info!("WebSocket for {name} joining room {room_id}");
    ws.max_message_size(MAX_MESSAGE_BYTES)
        .on_upgrade(move |socket| handle_socket(socket, state, room_id, name))
}

async fn handle_socket(
    socket: WebSocket,
    state: Arc<AppState>,
    room_id: String,
    user_name: String,
) {
    let (mut sender, mut receiver) = socket.split();
    let self_id = Uuid::new_v4();
    let info = ParticipantInfo {
        id: self_id,
        name: user_name,
        audio: true,
        video: true,
    };
    let (tx, mut rx) = mpsc::unbounded_channel();

    if let Err(JoinError::Full) = join_room(&state, &room_id, info, tx.clone()) {
        let full = ServerMessage::Error {
            message: "The room is full".to_string(),
        };
        let _ = send_message(&mut sender, &full).await;
        // 1008 (policy violation) tells the browser not to reconnect into the same full room.
        let close = Message::Close(Some(CloseFrame {
            code: 1008,
            reason: "The room is full".into(),
        }));
        let _ = sender.send(close).await;
        return;
    }

    let mut ping = tokio::time::interval(Duration::from_secs(PING_SECONDS));
    loop {
        tokio::select! {
            incoming = receiver.next() => match incoming {
                Some(Ok(Message::Text(text))) => {
                    handle_text(&text.to_string(), &state, &room_id, self_id, &tx);
                }
                Some(Ok(Message::Ping(payload))) => {
                    if sender.send(Message::Pong(payload)).await.is_err() {
                        break;
                    }
                }
                Some(Ok(Message::Close(_))) | None => break,
                Some(Ok(_)) => {}
                Some(Err(e)) => {
                    debug!("Socket error: {e}");
                    break;
                }
            },
            outbound = rx.recv() => match outbound {
                Some(message) => {
                    if send_message(&mut sender, &message).await.is_err() {
                        break;
                    }
                }
                None => break,
            },
            _ = ping.tick() => {
                if sender.send(Message::Ping(Vec::new().into())).await.is_err() {
                    break;
                }
            }
        }
    }

    leave_room(&state, &room_id, self_id);
    info!("Participant {self_id} left room {room_id}");
}

async fn send_message(
    sender: &mut SplitSink<WebSocket, Message>,
    message: &ServerMessage,
) -> Result<(), axum::Error> {
    let json = serde_json::to_string(message).map_err(|e| {
        warn!("Could not serialize a server message: {e}");
        axum::Error::new(e)
    })?;
    sender.send(Message::Text(json.into())).await
}

#[derive(Debug)]
enum JoinError {
    Full,
}

fn join_room(
    state: &AppState,
    room_id: &str,
    info: ParticipantInfo,
    tx: mpsc::UnboundedSender<ServerMessage>,
) -> Result<(), JoinError> {
    let mut rooms = state.rooms.lock().expect("rooms lock poisoned");
    let room = rooms
        .entry(room_id.to_string())
        .or_insert_with(Room::default);
    if room.participants.len() >= state.settings.max_participants {
        return Err(JoinError::Full);
    }

    room.participants.insert(
        info.id,
        Participant {
            info: info.clone(),
            tx: tx.clone(),
        },
    );

    let everyone: Vec<ParticipantInfo> = room
        .participants
        .values()
        .map(|participant| participant.info.clone())
        .collect();
    let joined = ServerMessage::PeerJoined {
        participant: info.clone(),
    };
    for (id, participant) in &room.participants {
        if *id != info.id {
            let _ = participant.tx.send(joined.clone());
        }
    }
    let _ = tx.send(ServerMessage::Welcome {
        self_id: info.id,
        room_id: room_id.to_string(),
        participants: everyone,
    });
    info!("Participant {} joined room {room_id}", info.id);
    Ok(())
}

fn leave_room(state: &AppState, room_id: &str, self_id: Uuid) {
    let mut rooms = state.rooms.lock().expect("rooms lock poisoned");
    let Some(room) = rooms.get_mut(room_id) else {
        return;
    };
    if room.participants.remove(&self_id).is_none() {
        return;
    }
    let left = ServerMessage::PeerLeft { id: self_id };
    for participant in room.participants.values() {
        let _ = participant.tx.send(left.clone());
    }
    if room.participants.is_empty() {
        rooms.remove(room_id);
        debug!("Room {room_id} is empty and has been removed");
    }
}

fn handle_text(
    text: &str,
    state: &AppState,
    room_id: &str,
    from: Uuid,
    self_tx: &mpsc::UnboundedSender<ServerMessage>,
) {
    let message: ClientMessage = match serde_json::from_str(text) {
        Ok(message) => message,
        Err(e) => {
            send_error(self_tx, format!("Invalid message: {e}"));
            return;
        }
    };

    match message {
        ClientMessage::Offer { to, sdp } => send_to(
            state,
            room_id,
            to,
            ServerMessage::Offer { from, sdp },
            self_tx,
        ),
        ClientMessage::Answer { to, sdp } => send_to(
            state,
            room_id,
            to,
            ServerMessage::Answer { from, sdp },
            self_tx,
        ),
        ClientMessage::IceCandidate { to, candidate } => send_to(
            state,
            room_id,
            to,
            ServerMessage::IceCandidate { from, candidate },
            self_tx,
        ),
        ClientMessage::Chat { text } => handle_chat(state, room_id, from, &text, self_tx),
        ClientMessage::State { audio, video } => {
            handle_state(state, room_id, from, audio, video, self_tx)
        }
    }
}

fn send_to(
    state: &AppState,
    room_id: &str,
    to: Uuid,
    message: ServerMessage,
    self_tx: &mpsc::UnboundedSender<ServerMessage>,
) {
    let rooms = state.rooms.lock().expect("rooms lock poisoned");
    let Some(room) = rooms.get(room_id) else {
        send_error(self_tx, "The room is gone");
        return;
    };
    let Some(target) = room.participants.get(&to) else {
        send_error(self_tx, "That participant has left");
        return;
    };
    let _ = target.tx.send(message);
}

fn handle_chat(
    state: &AppState,
    room_id: &str,
    from: Uuid,
    text: &str,
    self_tx: &mpsc::UnboundedSender<ServerMessage>,
) {
    let text = text.trim();
    if text.is_empty() {
        return;
    }
    if text.chars().count() > state.settings.chat_max_chars {
        send_error(self_tx, "That message is too long");
        return;
    }

    let rooms = state.rooms.lock().expect("rooms lock poisoned");
    let Some(room) = rooms.get(room_id) else {
        send_error(self_tx, "The room is gone");
        return;
    };
    let Some(sender) = room.participants.get(&from) else {
        return;
    };
    let message = ServerMessage::Chat {
        from,
        name: sender.info.name.clone(),
        text: text.to_string(),
        at: millis_now(),
    };
    for participant in room.participants.values() {
        let _ = participant.tx.send(message.clone());
    }
}

fn handle_state(
    state: &AppState,
    room_id: &str,
    from: Uuid,
    audio: bool,
    video: bool,
    self_tx: &mpsc::UnboundedSender<ServerMessage>,
) {
    let mut rooms = state.rooms.lock().expect("rooms lock poisoned");
    let Some(room) = rooms.get_mut(room_id) else {
        send_error(self_tx, "The room is gone");
        return;
    };
    let Some(sender) = room.participants.get_mut(&from) else {
        return;
    };
    sender.info.audio = audio;
    sender.info.video = video;
    let message = ServerMessage::ParticipantState {
        id: from,
        audio,
        video,
    };
    for participant in room.participants.values() {
        let _ = participant.tx.send(message.clone());
    }
}

fn send_error(tx: &mpsc::UnboundedSender<ServerMessage>, message: impl Into<String>) {
    let _ = tx.send(ServerMessage::Error {
        message: message.into(),
    });
}

fn millis_now() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|duration| duration.as_millis() as u64)
        .unwrap_or(0)
}

#[cfg(test)]
mod tests {
    use super::*;
    use axum::http::HeaderValue;
    use lib_axum_organizator::security::security_settings::SecurityConfig;

    fn test_state() -> AppState {
        AppState {
            settings: Settings::default(),
            jot: Jot::autogenerate(&SecurityConfig::default()).unwrap(),
            rooms: Mutex::new(HashMap::new()),
        }
    }

    #[test]
    fn origin_must_be_on_the_configured_list() {
        let mut headers = HeaderMap::new();
        headers.insert(
            header::ORIGIN,
            HeaderValue::from_static("https://example.test"),
        );
        assert!(origin_allowed(
            &headers,
            &["https://example.test".to_string()]
        ));
        assert!(!origin_allowed(
            &headers,
            &["https://other.test".to_string()]
        ));
        assert!(origin_allowed(&headers, &[]));
    }

    #[test]
    fn a_valid_identity_token_authenticates() {
        let state = test_state();
        let token = state.jot.generate_token("alice", &[]).unwrap();
        let mut headers = HeaderMap::new();
        headers.insert(
            header::COOKIE,
            HeaderValue::from_str(&format!("__Host-jwt={token}")).unwrap(),
        );
        let user = authenticate(&headers, &state.jot).unwrap();
        assert_eq!(user.id(), "alice");

        let mut bad = HeaderMap::new();
        bad.insert(header::COOKIE, HeaderValue::from_static("__Host-jwt=nope"));
        assert!(authenticate(&bad, &state.jot).is_err());
    }

    #[test]
    fn server_messages_use_the_wire_names_the_browser_reads() {
        let welcome = ServerMessage::Welcome {
            self_id: Uuid::nil(),
            room_id: "room".to_string(),
            participants: vec![ParticipantInfo {
                id: Uuid::nil(),
                name: "alice".to_string(),
                audio: true,
                video: false,
            }],
        };
        let json = serde_json::to_value(&welcome).unwrap();
        assert_eq!(json["type"], "welcome");
        assert_eq!(json["self_id"], Uuid::nil().to_string());
        assert_eq!(json["room_id"], "room");
        assert_eq!(json["participants"][0]["name"], "alice");
        assert_eq!(json["participants"][0]["video"], false);

        let chat = ServerMessage::Chat {
            from: Uuid::nil(),
            name: "alice".to_string(),
            text: "hi".to_string(),
            at: 12,
        };
        let json = serde_json::to_value(&chat).unwrap();
        assert_eq!(json["type"], "chat");
        assert_eq!(json["from"], Uuid::nil().to_string());

        let state = ServerMessage::ParticipantState {
            id: Uuid::nil(),
            audio: false,
            video: true,
        };
        assert_eq!(
            serde_json::to_value(&state).unwrap()["type"],
            "participant-state"
        );

        let candidate = ServerMessage::IceCandidate {
            from: Uuid::nil(),
            candidate: IceCandidate {
                candidate: "candidate:1".to_string(),
                sdp_mid: Some("0".to_string()),
                sdp_m_line_index: Some(0),
                username_fragment: None,
            },
        };
        let json = serde_json::to_value(&candidate).unwrap();
        assert_eq!(json["type"], "ice-candidate");
        assert_eq!(json["candidate"]["sdpMid"], "0");
        assert_eq!(json["candidate"]["sdpMLineIndex"], 0);
        assert!(json["candidate"]["usernameFragment"].is_null());
    }

    #[test]
    fn client_messages_are_read_with_the_browser_spelling() {
        let offer: ClientMessage = serde_json::from_str(
            r#"{"type":"offer","to":"00000000-0000-0000-0000-000000000000","sdp":"v=0"}"#,
        )
        .unwrap();
        assert!(matches!(offer, ClientMessage::Offer { .. }));

        let candidate: ClientMessage = serde_json::from_str(
            r#"{"type":"ice-candidate","to":"00000000-0000-0000-0000-000000000000",
                "candidate":{"candidate":"candidate:1","sdpMid":"0","sdpMLineIndex":0,
                             "usernameFragment":null}}"#,
        )
        .unwrap();
        match candidate {
            ClientMessage::IceCandidate { candidate, .. } => {
                assert_eq!(candidate.sdp_mid.as_deref(), Some("0"));
                assert_eq!(candidate.sdp_m_line_index, Some(0));
            }
            _ => panic!("the candidate was parsed as another message"),
        }
    }

    #[test]
    fn joining_notifies_the_room_and_leaving_empties_it() {
        let state = test_state();
        let (alice_tx, mut alice_rx) = mpsc::unbounded_channel();
        let alice = ParticipantInfo {
            id: Uuid::new_v4(),
            name: "alice".to_string(),
            audio: true,
            video: true,
        };
        join_room(&state, "room", alice.clone(), alice_tx).unwrap();
        assert!(matches!(
            alice_rx.try_recv(),
            Ok(ServerMessage::Welcome { .. })
        ));

        let (bob_tx, mut bob_rx) = mpsc::unbounded_channel();
        let bob = ParticipantInfo {
            id: Uuid::new_v4(),
            name: "bob".to_string(),
            audio: true,
            video: true,
        };
        join_room(&state, "room", bob.clone(), bob_tx).unwrap();
        assert!(matches!(
            alice_rx.try_recv(),
            Ok(ServerMessage::PeerJoined { .. })
        ));
        assert!(matches!(
            bob_rx.try_recv(),
            Ok(ServerMessage::Welcome {
                participants,
                ..
            }) if participants.len() == 2
        ));

        leave_room(&state, "room", bob.id);
        assert!(matches!(
            alice_rx.try_recv(),
            Ok(ServerMessage::PeerLeft { .. })
        ));
        assert_eq!(state.rooms.lock().unwrap()["room"].participants.len(), 1);

        leave_room(&state, "room", alice.id);
        assert!(state.rooms.lock().unwrap().is_empty());
    }
}
